<div class="overflow-x-auto rounded-3xl border border-white/10 bg-white/5"><table class="admin-table"><tr><th>Store</th><th>Email</th><th>Status</th><th>Balance</th><th>Action</th></tr><?php foreach ($vendors as $vendor): ?><tr><td><b><?= e($vendor['store_name']) ?></b><p class="text-xs text-slate-400"><?= e($vendor['headline']) ?></p></td><td><?= e($vendor['email']) ?></td><td><?= e($vendor['status']) ?> <?= $vendor['verified'] ? '✓' : '' ?></td><td><?= money($vendor['balance']) ?></td><td><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$vendor['id'] ?>"><select name="status" class="rounded bg-slate-900 p-2"><option value="approved">Approved</option><option value="pending">Pending</option><option value="rejected">Rejected</option></select><label class="ml-2"><input type="checkbox" name="verified" checked> Verified</label><button class="ml-2 text-cyan-300">Save</button></form></td></tr><?php endforeach; ?></table></div>
